async function deleteSolutionOnStudioWeb(baseUrl, organizationName, tenantId, accessToken, solutionId) {
  const url = `${baseUrl}/${organizationName}/studio_/backend/api/Solution/${encodeURIComponent(solutionId)}`;
  const response = await fetch(url, {
    method: "DELETE",
    headers: {
      Authorization: `Bearer ${accessToken}`,
      "x-uipath-tenantid": tenantId
    }
  });
  if (!response.ok) {
    const errorText = await response.text().catch(() => "(unreadable body)");
    throw new Error(`Delete failed (${response.status}): ${errorText}`);
  }
}
var registerDeleteCommand = (program) => {
  program.command("delete").description("Delete a solution from Studio Web by its solution ID. " + "The ID is emitted by 'solution upload' and 'flow debug' in their output." + (isPreviewBuild() ? " Find IDs with 'uip solution list'." : "")).argument("<solution-id>", "The Studio Web solution ID (UUID).").option("-y, --yes", "Confirm this irreversible operation (required; the CLI never prompts)").examples(SOLUTION_DELETE_EXAMPLES).trackedAction(processContext, async (solutionId, options) => {
    if (!requireConfirmation(options, `delete solution '${solutionId}'`)) {
      return;
    }
    const [loginError, loginStatus] = await catchError(getLoginStatusAsync({}));
    if (loginError) {
      const errorMessage = await extractErrorMessage(loginError);
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: errorMessage,
        Instructions: "Run 'uip login' to authenticate and try again."
      });
      processContext.exit(1);
      return;
    }
    if (loginStatus.loginStatus !== "Logged in" || !loginStatus.accessToken || !loginStatus.baseUrl || !loginStatus.organizationName || !loginStatus.tenantId) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Not logged in or login context incomplete. Run 'uip login' first.",
        Instructions: "Run 'uip login' to authenticate and try again."
      });
      processContext.exit(1);
      return;
    }
    logger.info(`Deleting solution ${solutionId} from Studio Web...`);
    const [deleteError] = await catchError(deleteSolutionOnStudioWeb(loginStatus.baseUrl, loginStatus.organizationName, loginStatus.tenantId, loginStatus.accessToken, solutionId));
    if (deleteError) {
      const errorMessage = await extractErrorMessage(deleteError);
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: errorMessage,
        Instructions: "Check that the solution ID is correct and that you have permission to delete it." + (isPreviewBuild() ? " Run 'uip solution list' to see the solutions you own or that are shared with you, and their IDs." : "")
      });
      processContext.exit(1);
      return;
    }
    OutputFormatter.success({
      Result: RESULTS.Success,
      Code: "SolutionDelete",
      Data: {
        SolutionId: solutionId
      }
    });
  });
};

