var registerDeployConfigLinkCommand = (program) => {
  program.command("link").description("Link a solution resource to an existing resource in Orchestrator instead of creating a new one during deployment. Example: 'config link config.json MyQueue --name ProductionQueue --folder-path Shared/Production'. Changes are local — pass the file to 'deploy run --config-file' to apply them.").argument("<file>", "Path to the deploy config JSON file. Generate one with 'solution deploy config get <package> -d config.json'.").argument("<resource>", "Resource name or resourceKey from the config file. Open the config JSON to see available resource names.").requiredOption("-n, --name <name>", "Name of the existing Orchestrator resource to link to. Use 'uip resources <kind> list' to find existing resources.").option("--folder-path <path>", "Orchestrator folder path where the existing resource lives. Use 'uip folders list' to see available folders.").examples(DEPLOY_CONFIG_LINK_EXAMPLES).trackedAction(processContext, async (file, resource, options) => {
    const [readError, result] = await readConfigFile(file);
    if (readError) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: readError.message,
        Instructions: "Provide a valid path to a deploy config JSON file."
      });
      processContext.exit(1);
      return;
    }
    const findResult = findResource(result.config, resource);
    if (findResult.error) {
      const errMsg = resourceErrorMessage(resource, findResult, result.config);
      OutputFormatter.error({
        Result: RESULTS.Failure,
        ...errMsg
      });
      processContext.exit(1);
      return;
    }
    const target = findResult.resource;
    const linkToResource = {
      name: options.name
    };
    if (options.folderPath) {
      linkToResource.folderPath = options.folderPath;
    }
    target.linkToResource = linkToResource;
    const writeError = await writeConfigFile(result.resolvedPath, result.config);
    if (writeError) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: `Failed to write config: ${writeError.message}`,
        Instructions: writeError.message
      });
      processContext.exit(1);
      return;
    }
    OutputFormatter.success({
      Result: RESULTS.Success,
      Code: "DeployConfigLink",
      Data: {
        Resource: target.name,
        LinkedTo: linkToResource
      }
    });
  });
};
var registerDeployConfigUnlinkCommand = (program) => {
  program.command("unlink").description("Remove a resource link from the config file. On the next 'deploy run --config-file', the resource will be unlinked from the existing Orchestrator resource and a new one will be created instead.").argument("<file>", "Path to the deploy config JSON file. Generate one with 'solution deploy config get <package> -d config.json'.").argument("<resource>", "Resource name or resourceKey from the config file. Open the config JSON to see available resource names and their current links.").examples(DEPLOY_CONFIG_UNLINK_EXAMPLES).trackedAction(processContext, async (file, resource) => {
    const [readError, result] = await readConfigFile(file);
    if (readError) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: readError.message,
        Instructions: "Provide a valid path to a deploy config JSON file."
      });
      processContext.exit(1);
      return;
    }
    const findResult = findResource(result.config, resource);
    if (findResult.error) {
      const errMsg = resourceErrorMessage(resource, findResult, result.config);
      OutputFormatter.error({
        Result: RESULTS.Failure,
        ...errMsg
      });
      processContext.exit(1);
      return;
    }
    const target = findResult.resource;
    if (!target.linkToResource) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: `Resource '${target.name}' is not linked to any Orchestrator resource`,
        Instructions: "Use 'solution deploy config link' to create a link first."
      });
      processContext.exit(1);
      return;
    }
    const previousLink = target.linkToResource;
    delete target.linkToResource;
    const writeError = await writeConfigFile(result.resolvedPath, result.config);
    if (writeError) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: `Failed to write config: ${writeError.message}`,
        Instructions: writeError.message
      });
      processContext.exit(1);
      return;
    }
    OutputFormatter.success({
      Result: RESULTS.Success,
      Code: "DeployConfigUnlink",
      Data: {
        Resource: target.name,
        UnlinkedFrom: previousLink.name
      }
    });
  });
};

