// src/commands/deploy-list.ts
var OPERATION_STATUS_VALUES = Object.values(DeploymentOperationStatus);
var ACTIVATION_STATUS_VALUES = Object.values(DeploymentActivationStatus);
function parseStatusFilter(raw, allowed, flag) {
  if (raw === undefined) {
    return { ok: true, values: undefined };
  }
  const values = raw.split(",").map((value) => value.trim()).filter((value) => value.length > 0);
  if (values.length === 0) {
    return {
      ok: false,
      message: `No values provided for ${flag}.`,
      instructions: `${flag} must be a comma-separated list of: ${allowed.join(", ")}`
    };
  }
  const invalid = values.filter((value) => !allowed.includes(value));
  if (invalid.length > 0) {
    return {
      ok: false,
      message: `Invalid ${flag} value(s): ${invalid.join(", ")}`,
      instructions: `${flag} must be a comma-separated list of: ${allowed.join(", ")}`
    };
  }
  return { ok: true, values };
}
