var registerDeployStatusCommand = (program) => {
  program.command("status").description("Check the current status of a pipeline deployment. Returns deployment state, progress, and any errors.").argument("<pipeline-deployment-id>", "Pipeline deployment ID (GUID) returned by 'solution deploy run'.").addOption(createHiddenDeprecatedTenantOption("-t, --tenant <tenant-name>")).option("--login-validity <minutes>", "Minimum minutes before token expiration to trigger a refresh (default: 10)", parseInt, 10).examples(SOLUTION_DEPLOY_STATUS_EXAMPLES).trackedAction(processContext, async (pipelineDeploymentId, options) => {
    const [authError, auth] = await catchError(getSolutionAuthContext({
      tenant: options.tenant,
      loginValidity: options.loginValidity
    }));
    if (authError) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: authError.message,
        Instructions: authError.message
      });
      processContext.exit(1);
      return;
    }
    const configuration = new Configuration({
      basePath: auth.basePath,
      accessToken: auth.accessToken
    });
    const api = new PipelinesApi(configuration);
    const [statusError, result] = await catchError(api.pipelinesGetPipelineDeploymentStatus({
      pipelineDeploymentId
    }));
    if (statusError) {
      const { message, details } = await extractErrorDetails(statusError);
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: message,
        Instructions: `Check the pipeline deployment ID. Get it from deploy run output. Details: ${details}`
      });
      processContext.exit(1);
      return;
    }
    const errors = extractDeploymentErrors(result);
    const errorsText = errors ? formatDeploymentErrorsAsText(errors) : undefined;
    OutputFormatter.success({
      Result: RESULTS.Success,
      Code: "SolutionDeployStatus",
      Data: {
        PipelineDeploymentId: pipelineDeploymentId,
        Status: result.status,
        DeploymentKey: result.deploymentKey,
        ConfigurationKey: result.configurationKey,
        InstanceId: result.instanceId,
        DeploymentResult: result.deploymentResult ? {
          Name: result.deploymentResult.deploymentName,
          PackageName: result.deploymentResult.packageName,
          PackageVersion: result.deploymentResult.packageVersion,
          Status: result.deploymentResult.status,
          StartDate: result.deploymentResult.startDate,
          EndDate: result.deploymentResult.endDate,
          Errors: errorsText
        } : errorsText ? { Errors: errorsText } : null
      }
    });
  });
};

