var registerPackagesDownloadCommand = (program) => {
  program.command("download").description("Download a published solution package (.zip) from the current tenant's feed. " + "Use 'solution packages list' to find available package names and versions. " + "The package must be Ready or Active.").argument("<package-name>", "Solution package name. Use 'solution packages list' to find available names.").argument("[package-version]", "Package version to download (optional, latest if omitted)").option("--package-version <version>", "Package version (optional, latest if omitted)").option("-d, --destination <path>", "Local .zip file path or directory. Defaults to the current directory.").addOption(createHiddenDeprecatedTenantOption("-t, --tenant <tenant-name>")).option("--login-validity <minutes>", "Minimum minutes before token expiration to trigger a refresh (default: 10)", parseInt, 10).examples(SOLUTION_PACKAGES_DOWNLOAD_EXAMPLES).trackedAction(processContext, async (packageName, packageVersionArg, options) => {
    const requestedVersion = packageVersionArg ?? options.packageVersion;
    if (packageVersionArg && options.packageVersion && packageVersionArg !== options.packageVersion) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Conflicting package versions provided.",
        Instructions: "Use either the positional package version or --package-version, not both."
      });
      processContext.exit(1);
      return;
    }
    const [authError, auth] = await catchError(getSolutionAuthContext({
      tenant: options.tenant,
      loginValidity: options.loginValidity
    }));
    if (authError) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: authError.message,
        Instructions: LOGIN_INSTRUCTIONS
      });
      processContext.exit(1);
      return;
    }
    const configuration = new Configuration({
      basePath: auth.basePath,
      accessToken: auth.accessToken
    });
    const api = new PipelinesApi(configuration);
    const [packageError, packageInfo] = await catchError(api.pipelinesGetPackageVersion({
      packageName,
      packageVersion: requestedVersion
    }));
    if (packageError) {
      const { message, details } = await extractErrorDetails(packageError);
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: message,
        Instructions: `Check available packages with: uip solution packages list. Details: ${details}`
      });
      processContext.exit(1);
      return;
    }
    if (!PACKAGE_READY_STATES.has(packageInfo.state)) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: `Package is in ${packageInfo.state} state.`,
        Instructions: getPackageStateInstructions(packageInfo.state)
      });
      processContext.exit(1);
      return;
    }
    const [downloadError, blobAccess] = await catchError(api.pipelinesPackageDownload({
      packageName,
      packageVersion: packageInfo.packageVersion
    }));
    if (downloadError) {
      const { message, details } = await extractErrorDetails(downloadError);
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: message,
        Instructions: `Failed to request package download. Details: ${details}`
      });
      processContext.exit(1);
      return;
    }
    if (!blobAccess?.uri) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Download URL missing from API response",
        Instructions: "Pipelines API did not return a download URI; retry, or contact UiPath support if the issue persists."
      });
      processContext.exit(1);
      return;
    }
    const fs = getFileSystem();
    const outputArg = options.destination ?? ".";
    const defaultName = `${packageInfo.packageName}.${packageInfo.packageVersion}.zip`;
    const outputPath = await resolveOutputPath(fs, outputArg, defaultName);
    const [fileError, size] = await catchError(downloadFile(fs, blobAccess.uri, outputPath));
    if (fileError) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Failed to download solution package",
        Instructions: fileError.message
      });
      processContext.exit(1);
      return;
    }
    OutputFormatter.success({
      Result: RESULTS.Success,
      Code: "SolutionPackagesDownload",
      Data: {
        Status: "Package downloaded",
        PackageName: packageInfo.packageName,
        PackageVersion: packageInfo.packageVersion,
        State: packageInfo.state,
        OutputPath: outputPath,
        FileName: outputPath,
        Size: size
      }
    });
  });
};
async function downloadFile(fs, uri, outputPath) {
  const response = await fetch(uri);
  if (!response.ok) {
    throw new Error(`Solution package download returned HTTP ${response.status}.`);
  }
  const content = Buffer.from(await response.arrayBuffer());
  if (content.length === 0) {
    throw new Error("Solution package download returned an empty response body.");
  }
  const [writeError] = await catchError(fs.writeFile(outputPath, content));
  if (writeError) {
    throw new Error(`Could not write to '${outputPath}': ${writeError.message}`);
  }
  return content.byteLength;
}
async function resolveOutputPath(fs, outputArg, defaultName) {
  const trimmed = outputArg.replace(/[\\/]+$/, "");
  const hadTrailingSeparator = outputArg !== trimmed;
  const looksLikeDir = trimmed === "" || trimmed === "." || hadTrailingSeparator;
  if (looksLikeDir) {
    return fs.path.join(trimmed === "" ? "." : trimmed, defaultName);
  }
  const exists = await fs.exists(outputArg);
  if (exists) {
    const hasExtension = /\.[^./\\]+$/.test(outputArg);
    if (!hasExtension) {
      return fs.path.join(outputArg, defaultName);
    }
  }
  return outputArg;
}

