async function hasProjectInSolution(fs, solutionDir, projectDir, projects) {
  const projectDirReal = await canonicalizePath(fs, projectDir);
  for (const project of projects ?? []) {
    const candidateDir = fs.path.resolve(solutionDir, fs.path.dirname(toPortableRelativePath(project.ProjectRelativePath)));
    const candidateReal = await canonicalizePath(fs, candidateDir);
    if (candidateReal === projectDirReal) {
      return true;
    }
  }
  return false;
}
async function canonicalizePath(fs, path) {
  const [error, realPath] = await catchError(fs.realpath(path));
  return error || !realPath ? path : realPath;
}
