var registerProjectImportCommand = (project) => {
  project.command("import").description("Copy an external project folder into the solution directory and register it in the .uipx manifest. Unlike 'projects add' which references an existing subfolder, import copies the source files into the solution tree.").argument("<source>", "Path to the project folder to import (must contain project.uiproj, project.json, or uipath.json)").option("--solutionFile <path>", "Path to the .uipx solution file (defaults to the nearest .uipx file found by searching up from the current directory)").examples(PROJECT_IMPORT_EXAMPLES).trackedAction(processContext, async (sourcePath, options) => {
    const { solutionFile } = options;
    const fs = getFileSystem();
    const cwd = fs.env.cwd();
    const resolvedSourcePath = fs.path.resolve(cwd, sourcePath);
    const [statError, sourceStats] = await catchError(fs.stat(resolvedSourcePath));
    if (statError) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Failed to import project into solution",
        Instructions: statError.message
      });
      processContext.exit(1);
      return;
    }
    if (!sourceStats) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Failed to import project into solution",
        Instructions: `Source project folder not found: ${resolvedSourcePath}`
      });
      processContext.exit(1);
      return;
    }
    if (!sourceStats.isDirectory()) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Failed to import project into solution",
        Instructions: `Source path is not a directory: ${resolvedSourcePath}`
      });
      processContext.exit(1);
      return;
    }
    const [projectFileError, projectFileInfo] = await findProjectFile(resolvedSourcePath);
    if (projectFileError) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Failed to import project into solution",
        Instructions: projectFileError.message
      });
      processContext.exit(1);
      return;
    }
    const [readProjectError, parsedProject] = await readProjectFile(projectFileInfo.filePath, projectFileInfo.useProjectJson);
    if (readProjectError) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Failed to import project into solution",
        ...isProjectManifestError(readProjectError) ? { ErrorCode: "invalid_argument" } : {},
        Instructions: projectManifestInstructions(projectFileInfo.fileName, readProjectError, "import")
      });
      processContext.exit(1);
      return;
    }
    if (rejectUnsupportedProjectType(parsedProject.projectType, "Failed to import project into solution")) {
      return;
    }
    const [solutionFileError, resolvedSolutionFile] = await resolveSolutionFilePath(solutionFile, cwd);
    if (solutionFileError) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Failed to import project into solution",
        Instructions: solutionFileError.message
      });
      processContext.exit(1);
      return;
    }
    const solutionDir = fs.path.dirname(resolvedSolutionFile);
    const projectFolderName = fs.path.basename(resolvedSourcePath);
    const targetProjectPath = fs.path.join(solutionDir, projectFolderName);
    const targetAlreadyExists = await fs.exists(targetProjectPath);
    if (targetAlreadyExists) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Failed to import project into solution",
        Instructions: `Project already exists at destination: ${targetProjectPath}`
      });
      processContext.exit(1);
      return;
    }
    const [readSolutionError, parsedSolution] = await readSolutionFile(resolvedSolutionFile);
    if (readSolutionError) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Failed to import project into solution",
        Instructions: readSolutionError.message
      });
      processContext.exit(1);
      return;
    }
    const { solution, rawContent: originalSolutionContent } = parsedSolution;
    const projectRelativePath = toPortableRelativePath(fs.path.join(projectFolderName, projectFileInfo.fileName));
    const alreadyExists = solution.Projects?.some((p) => toPortableRelativePath(p.ProjectRelativePath) === projectRelativePath);
    if (alreadyExists) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Failed to import project into solution",
        Instructions: `Project already exists in solution manifest: ${projectRelativePath}`
      });
      processContext.exit(1);
      return;
    }
    const [copyError] = await catchError(fs.copyDirectory(resolvedSourcePath, targetProjectPath));
    if (copyError) {
      await catchError(fs.rm(targetProjectPath));
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Failed to import project into solution",
        Instructions: `Failed to copy project: ${copyError.message}`
      });
      processContext.exit(1);
      return;
    }
    const projectId = randomUUID2();
    const projectName = parsedProject.content.Name ?? projectFolderName;
    if (!solution.Projects) {
      solution.Projects = [];
    }
    solution.Projects.push({
      Type: parsedProject.projectType,
      ProjectRelativePath: projectRelativePath,
      Id: projectId
    });
    const writeError = await writeSolutionFile(resolvedSolutionFile, solution);
    if (writeError) {
      await catchError(fs.rm(targetProjectPath));
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Failed to import project into solution",
        Instructions: writeError.message
      });
      processContext.exit(1);
      return;
    }
    const rollback = async () => {
      await catchError(fs.rm(targetProjectPath));
      await catchError(fs.writeFile(resolvedSolutionFile, originalSolutionContent));
    };
    const resourcesPending = resourcesPendingForProjectType(parsedProject.projectType);
    const createError = hostGeneratesResources(parsedProject.projectType) ? await createProjectInSolutionBuilder(solutionDir, projectId, projectName, parsedProject.projectType) : null;
    if (createError) {
      await rollback();
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Failed to import project into solution",
        Instructions: createError.message
      });
      processContext.exit(1);
      return;
    }
    const syncResult = await syncResourcesFromBindings(solutionDir, [targetProjectPath]);
    for (const warning of syncResult.warnings) {
      logger.warn(warning);
    }
    if (resourcesPending) {
      logger.warn(resourcesPendingWarning(parsedProject.projectType));
    }
    OutputFormatter.success({
      Result: RESULTS.Success,
      Code: "ProjectImport",
      Data: {
        Status: "Imported successfully",
        Project: projectRelativePath,
        Solution: resolvedSolutionFile,
        ResourcesPending: resourcesPending
      }
    });
  });
};

// src/commands/project-list.ts
async function readProjectName(fs, projectFilePath) {
  const [readError, content] = await catchError(fs.readFile(projectFilePath, "utf-8"));
  if (readError)
    return;
  const [parseError, parsed] = catchError(() => JSON.parse(content));
  if (parseError || !parsed || typeof parsed !== "object")
    return;
  const name = parsed.Name;
  return typeof name === "string" && name.length > 0 ? name : undefined;
}
function fallbackProjectName(fs, solutionDir, projectRelativePath) {
  const projectDir = fs.path.dirname(projectRelativePath);
  return projectDir && projectDir !== "." ? fs.path.basename(projectDir) : fs.path.basename(solutionDir);
}
