async function listResources(builder, services, source, kind, search, includeVersion = false) {
  const entries = await collectResources(builder, services, source, kind, search);
  if (includeVersion) {
    await annotateVersions(services, builder, entries);
  }
  return entries;
}
async function collectResources(builder, services, source, kind, search) {
  const includeLocal = source === "local" || source === "all";
  const includeRemote = source === "remote" || source === "all";
  if (kind) {
    return querySingleKind(builder, kind, search, includeLocal, includeRemote);
  }
  const all = [];
  if (includeLocal) {
    all.push(...await listLocalResources(builder, undefined, search));
  }
  if (includeRemote) {
    const remote = await listAllRemoteResources(services, search);
    const localKeys = new Set(all.map((e) => `${e.Kind}:${e.Name}`.toLowerCase()));
    const uniqueRemote = remote.filter((r) => !localKeys.has(`${r.Kind}:${r.Name}`.toLowerCase()));
    all.push(...uniqueRemote);
  }
  return all;
}
function versionLookupId(entry) {
  return `${entry.Source}|${entry.Key}|${entry.Folder ?? ""}`;
}
async function annotateVersions(services, builder, entries) {
  const targets = new Map;
  for (const entry of entries) {
    if (entry.Key === "") {
      continue;
    }
    const id = versionLookupId(entry);
    if (targets.has(id)) {
      continue;
    }
    targets.set(id, {
      id,
      key: entry.Key,
      kind: entry.Kind,
      type: entry.Type,
      name: entry.Name,
      source: entry.Source === "Local" ? "Local" : "Remote",
      folderFullyQualifiedName: entry.Folder,
      folderKey: entry.FolderKey
    });
  }
  const versions = await resolveResourceVersionsAsync(services, builder, [
    ...targets.values()
  ]);
  for (const entry of entries) {
    const version = versions.get(versionLookupId(entry));
    if (version !== undefined) {
      entry.Version = version;
    }
  }
}
async function listAllRemoteResources(services, search) {
  const rcs = services.container.resolve(Tokens.IResourceCatalogClientProxy);
  const entries = [];
  let pageCursor;
  do {
    const [err, result] = await catchError(rcs.searchFolderEntities({
      name: search,
      pageSize: 100,
      pageCursor
    }));
    if (err) {
      logger.warn(`Failed to search remote resources: ${err.message}`);
      return entries;
    }
    for (const item of result.items ?? []) {
      entries.push({
        Source: "Remote",
        Key: item.entityKey ?? "",
        Name: item.entityName ?? "",
        Kind: item.entityType ?? "",
        Type: item.entitySubType ?? undefined,
        Folder: item.fullyQualifiedName,
        FolderKey: item.folderKey
      });
    }
    pageCursor = result.nextPage ?? undefined;
  } while (pageCursor);
  return entries;
}
async function listLocalResources(builder, kind, search) {
  const solution = await builder.context.loadAsync();
  let resources = solution.resources ?? [];
  if (kind) {
    resources = resources.filter((r) => r.kind?.toLowerCase() === kind.toLowerCase());
  }
  if (search) {
    const term = search.toLowerCase();
    resources = resources.filter((r) => r.name?.toLowerCase().includes(term));
  }
  return resources.map((r) => ({
    Source: "Local",
    Key: r.key ?? "",
    Name: r.name ?? "",
    Kind: r.kind ?? "",
    Type: r.type,
    Folder: r.folders?.[0]?.fullyQualifiedName
  }));
}
async function querySingleKind(builder, kind, search, includeLocal, includeRemote) {
  const entries = [];
  if (includeLocal) {
    entries.push(...await listLocalResources(builder, kind, search));
  }
  if (includeRemote) {
    let pageCursor;
    do {
      const result = await builder.searchResourcesAsync(kind, undefined, search, pageCursor, 100, undefined, false);
      for (const folder of result.availableResources ?? []) {
        for (const r of folder.resources ?? []) {
          entries.push({
            Source: "Remote",
            Key: r.key,
            Name: r.name,
            Kind: r.kind,
            Type: r.type,
            Folder: folder.fullyQualifiedName,
            FolderKey: folder.key
          });
        }
      }
      pageCursor = result.nextPage;
    } while (pageCursor);
  }
  if (includeLocal && includeRemote) {
    const localKeys = new Set(entries.filter((e) => e.Source === "Local").map((e) => `${e.Kind}:${e.Name}`.toLowerCase()));
    return entries.filter((e) => e.Source === "Local" || !localKeys.has(`${e.Kind}:${e.Name}`.toLowerCase()));
  }
  return entries;
}

